test("void settled scenario 2", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-04-05");
  expect(await ui.setRole(pg_uma, "wes", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "late-pct", "5.00");
  await ui.setSetting(pg_uma, "policy-date", "2026-03-05");
  await ui.setSetting(pg_uma, "terms-A", "3");
  await ui.setSetting(pg_uma, "perm-close", "steward");
  expect(await ui.setRole(pg_uma, "vic", "viewer")).toBe(true);
  await ui.setSetting(pg_uma, "grace-days", "3");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "33.33"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "33.33"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "33.33", "from": "2026-03-16"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "C"}));
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "B", "terms": "20"}));
  const c_ada_0 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "25.00"}));
  const c_ada_1 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "10.35"}));
  expect(await ui.claimAction(pg_uma, c_ada_1, "open")).toBe(true);
  const pg_vic = await ui.userPage(browser, "vic", sheet);
  expect(await ui.claimAction(pg_vic, c_ada_0, "open")).toBe(false);
  expect(await ui.claimAction(pg_vic, c_ada_0, "open")).toBe(false);
  expect(await ui.exportCsv(pg_vic)).toBe("name,grade,retired-from,due-total\nCam,C,,n/a\nAda,B,,3.45\n");
  expect(await ui.statement(pg_vic, p_cam)).toBe(false);
  await ui.refresh(pg_vic);
  await expect(pg_vic.getByTestId("person-row-" + p_cam).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_vic.getByTestId("person-row-" + p_cam).getByTestId("person-due-total")).toHaveText("n/a");
  await expect(pg_vic.getByTestId("person-row-" + p_ada).getByTestId("person-claimed")).toHaveText("10.35");
  await expect(pg_vic.getByTestId("person-row-" + p_ada).getByTestId("person-due-total")).toHaveText("3.45");
  await expect(pg_vic.getByTestId("claim-row-" + c_ada_1).getByTestId("claim-due")).toHaveText("3.45");
  await expect(pg_vic.getByTestId("claim-row-" + c_ada_1).getByTestId("claim-status")).toHaveText("OPEN");
  await expect(pg_vic.getByTestId("claim-row-" + c_ada_1).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_vic.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-due")).toHaveText("8.33");
  await expect(pg_vic.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-status")).toHaveText("DRAFT");
  await expect(pg_vic.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_vic.getByTestId("rollup-claimed-total")).toHaveText("10.35");
  await expect(pg_vic.getByTestId("rollup-due-total")).toHaveText("3.45");
  await expect(pg_vic.getByTestId("rollup-overdue-count")).toHaveText("0");
  await expect(pg_vic.getByTestId("rollup-overdue-total")).toHaveText("0.00");
  await expect(pg_vic.getByTestId("header-people-count")).toHaveText("2");
  await expect(pg_vic.getByTestId("header-claims-DRAFT-count")).toHaveText("1");
  await expect(pg_vic.getByTestId("header-claims-OPEN-count")).toHaveText("1");
  await expect(pg_vic.getByTestId("header-claims-PENDING-count")).toHaveText("0");
  await expect(pg_vic.getByTestId("header-claims-SETTLED-count")).toHaveText("0");
  await expect(pg_vic.getByTestId("header-claims-VOID-count")).toHaveText("0");
  await expect(pg_vic.getByTestId("header-due-total")).toHaveText("3.45");
  await expect(pg_vic.getByTestId("header-overdue-total")).toHaveText("0.00");
  expect(await ui.hold(pg_vic, p_cam, {"from": "2026-03-05", "to": "2026-03-28"})).toBe(false);
  expect(await ui.periodAction(pg_vic, "P1", "close")).toBe(false);
  expect(await ui.addClaim(pg_vic, p_cam, {"amount": "10.35"})).toBeNull();
  expect(await ui.addPatron(pg_vic, p_ada, "Cam")).toBe(false);
  expect(await ui.claimAction(pg_vic, c_ada_1, "void")).toBe(false);
  expect(await ui.statement(pg_vic, p_ada)).toBe(false);
  expect(await ui.claimAction(pg_vic, c_ada_1, "settle")).toBe(false);
test("void settled scenario 3", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
